insert into practice_generated_content (
) values (
) on conflict ( owner_key, owner_key_version, surface, mode, request_fingerprint, prompt_version, strategy_version , policy_version ) where status in ('draft', 'active', 'promoted') do nothing returning

select 
from practice_generated_content
where owner_key = #{ownerKey}
  and owner_key_version = #{ownerKeyVersion}
  and surface = #{surface}
  and mode = #{mode}
  and request_fingerprint = #{requestFingerprint}
  and prompt_version = #{promptVersion}
  and strategy_version = #{strategyVersion}
  and policy_version = #{policyVersion}
  and status in ('draft', 'active', 'promoted')
order by case status
            when 'active' then 0
            when 'promoted' then 1
            else 2
         end,
         updated_at desc,
         generated_content_id asc
limit 1

mapper.update:
update practice_generated_content
set status = 'rejected',
    generation_error_code = #{generationErrorCode},
    normalized_scene_text = null,
    retention_expires_at = case
        when owner_scope = 'installation'
            then #{retentionExpiresAt,typeHandler=org.apache.ibatis.type.OffsetDateTimeTypeHandler}
        else null
    end,
    updated_at = #{updatedAt,typeHandler=org.apache.ibatis.type.OffsetDateTimeTypeHandler}
where generated_content_id = #{generatedContentId}
  and status = 'draft'

update practice_generated_content
set status = 'expired',
    generation_error_code = #{generationErrorCode},
    generation_expires_at = #{updatedAt,typeHandler=org.apache.ibatis.type.OffsetDateTimeTypeHandler},
    normalized_scene_text = null,
    retention_expires_at = case
        when owner_scope = 'installation'
            then #{retentionExpiresAt,typeHandler=org.apache.ibatis.type.OffsetDateTimeTypeHandler}
        else null
    end,
    updated_at = #{updatedAt,typeHandler=org.apache.ibatis.type.OffsetDateTimeTypeHandler}
where generated_content_id = #{generatedContentId}
  and status = 'draft'

update practice_generated_content
set status = 'expired',
    generation_error_code = 'retention_expired',
    normalized_scene_text = null,
    updated_at = #{updatedAt,typeHandler=org.apache.ibatis.type.OffsetDateTimeTypeHandler}
where generated_content_id = #{generatedContentId}
  and owner_key_version = #{ownerKeyVersion}
  and owner_scope = 'installation'
  and status = 'active'
  and retention_expires_at <= #{updatedAt,typeHandler=org.apache.ibatis.type.OffsetDateTimeTypeHandler}

mapper.select:
select 
from practice_generated_content
where generated_content_id = #{generatedContentId}
  and owner_key_version = #{ownerKeyVersion}
  and status in ('active', 'promoted')
  and (owner_scope <> 'installation' or retention_expires_at > #{reusableAt,typeHandler=org.apache.ibatis.type.OffsetDateTimeTypeHandler})

select 
from practice_generated_content
where owner_key = #{ownerKey}
  and owner_key_version = #{ownerKeyVersion}
  and surface = #{surface}
  and mode = #{mode}
  and request_fingerprint = #{requestFingerprint}
  and prompt_version = #{promptVersion}
  and strategy_version = #{strategyVersion}
  and policy_version = #{policyVersion}
  and status in ('active', 'promoted')
  and (owner_scope <> 'installation' or retention_expires_at > #{reusableAt,typeHandler=org.apache.ibatis.type.OffsetDateTimeTypeHandler})
order by case status
            when 'active' then 0
            else 1
         end,
         updated_at desc,
         generated_content_id asc
limit 1

select count(*)
from practice_generated_content
where owner_key = #{ownerKey}
  and owner_key_version = #{ownerKeyVersion}
  and surface = #{surface}
  and mode = #{mode}
  and created_at >= #{createdAtFrom,typeHandler=org.apache.ibatis.type.OffsetDateTimeTypeHandler}
  and status in ('draft', 'rejected', 'expired', 'active', 'promoted')

select 
from practice_generated_content
where owner_scope = 'installation'
  and owner_key_version = #{ownerKeyVersion}
  and installation_ref_hash = #{installationRefHash}
  and status in ('active', 'expired', 'rejected')
  and retention_expires_at <= #{retentionExpiresAtOrBefore,typeHandler=org.apache.ibatis.type.OffsetDateTimeTypeHandler}
order by retention_expires_at asc, generated_content_id asc
limit #{limit}

mapper.update:
with candidates as (
    select generated_content_id
    from practice_generated_content
    where status = 'draft'
      and generation_expires_at <= #{generationExpiresAtOrBefore,typeHandler=org.apache.ibatis.type.OffsetDateTimeTypeHandler}
    order by generation_expires_at asc, generated_content_id asc
    limit #{limit}
    for update skip locked
)
update practice_generated_content target
set status = 'expired',
    generation_error_code = 'draft_expired',
    normalized_scene_text = null,
    retention_expires_at = case
        when target.owner_scope = 'installation'
            then #{installationRetentionExpiresAt,typeHandler=org.apache.ibatis.type.OffsetDateTimeTypeHandler}
        else null
    end,
    updated_at = #{updatedAt,typeHandler=org.apache.ibatis.type.OffsetDateTimeTypeHandler}
from candidates
where target.generated_content_id = candidates.generated_content_id
  and target.status = 'draft'
  and target.generation_expires_at <= #{generationExpiresAtOrBefore,typeHandler=org.apache.ibatis.type.OffsetDateTimeTypeHandler}

mapper.delete:
delete from practice_generated_content
where account_id = #{accountId}
  and owner_scope in ('account', 'profile')
